mapper.update:
UPDATE sys_module
SET frozen = #{frozen,jdbcType=INTEGER}
WHERE id = #{id,jdbcType=BIGINT}

    OR path LIKE CONCAT(#{path,jdbcType=VARCHAR}, '/%')

UPDATE sys_module
SET sort = CASE
    WHEN id = #{id} THEN #{newSort}
    WHEN #{newSort} < #{oldSort}
        AND sort >= #{newSort}
        AND sort < #{oldSort} THEN sort + 1
    WHEN #{newSort} > #{oldSort}
        AND sort <= #{newSort}
        AND sort > #{oldSort} THEN sort - 1
    ELSE sort
END
WHERE pid = #{pid,jdbcType=BIGINT}
  AND (
      (sort BETWEEN LEAST(#{oldSort}, #{newSort}) AND GREATEST(#{oldSort}, #{newSort}))
      OR id = #{id}
  )

mapper.select:
SELECT count(id)
FROM sys_module
WHERE pid = #{id,jdbcType=BIGINT}

SELECT

FROM SYS_MODULE t

    (t.DELETED = 0 OR t.DELETED IS NULL)

        AND t.ID = #{bo.id}


        AND t.NAME LIKE CONCAT('%', #{bo.name}, '%')


        AND t.PID = #{bo.pid}


        AND t.CODE = #{bo.code}


ORDER BY t.SORT ASC
